<script setup lang="ts">
import { getArticle } from '~/data/articles'; import { getRace } from '~/data/races'; import { getRunner } from '~/data/runners'; import { getTrailRoute } from '~/data/routes'
const pageRoute=useRoute(); const article=computed(()=>getArticle(pageRoute.params.slug as string)); if(!article.value) throw createError({statusCode:404,statusMessage:'Članek ni najden'}); useSiteSeo(()=>article.value?.title,()=>article.value?.description)
const related=computed(()=>{ if(!article.value)return []; const list=[]; if(article.value.relatedRace){const v=getRace(article.value.relatedRace);if(v)list.push({label:'Povezana tekma',name:v.name,to:`/races/${v.slug}`})} if(article.value.relatedRunner){const v=getRunner(article.value.relatedRunner);if(v)list.push({label:'Povezan tekač',name:v.name,to:`/runners/${v.slug}`})} if(article.value.relatedRoute){const v=getTrailRoute(article.value.relatedRoute);if(v)list.push({label:'Povezana trasa',name:v.name,to:`/routes/${v.slug}`})} return list})
</script>
<template><article v-if="article" class="story-page"><header class="story-header shell"><p class="eyebrow">{{ article.category }} · {{ new Date(article.publishedAt).toLocaleDateString('sl-SI') }}</p><h1>{{ article.title }}</h1><p>{{ article.description }}</p></header><div class="story-image"><img :src="article.image" :alt="article.title"></div><div class="story-layout shell"><aside><span class="mono">TRAIL JOURNAL / {{ article.id.toUpperCase() }}</span><p>Demo uredniška vsebina</p></aside><div class="story-body"><p v-for="paragraph in article.body" :key="paragraph">{{ paragraph }}</p></div></div><section v-if="related.length" class="related-entities shell"><p class="eyebrow">Povezano</p><NuxtLink v-for="item in related" :key="item.to" :to="item.to"><span>{{ item.label }}</span><strong>{{ item.name }}</strong><em>↗</em></NuxtLink></section></article></template>
